privateKey.description:
The private key for used by the crypto module to create signed tokens or encrypt data.
@default ""
@environment `AFFINE_PRIVATE_KEY`

SMTP.name.description:
Hostname used for SMTP HELO/EHLO (e.g. mail.example.com). Leave empty to use the system hostname.
@default ""
@environment `MAILER_SERVERNAME`

SMTP.host.description:
Host of the email server (e.g. smtp.gmail.com)
@default ""
@environment `MAILER_HOST`

SMTP.port.description:
Port of the email server (they commonly are 25, 465 or 587)
@default 465
@environment `MAILER_PORT`

SMTP.username.description:
Username used to authenticate the email server
@default ""
@environment `MAILER_USER`

SMTP.password.description:
Password used to authenticate the email server
@default ""
@environment `MAILER_PASSWORD`

SMTP.sender.description:
Sender of all the emails (e.g. "LocalMind Self Hosted &lt;noreply@example.com&gt;")
@default "LocalMind Self Hosted <noreply@example.com>"
@environment `MAILER_SENDER`

SMTP.ignoreTLS.description:
Whether ignore email server's TLS certificate verification. Enable it for self-signed certificates.
@default false
@environment `MAILER_IGNORE_TLS`

transports.description:
The enabled transports for accepting websocket traffics.
@default ["websocket","polling"]
@link https://docs.nestjs.com/websockets/gateways#transports

externalUrl.description:
Base URL of the LocalMind server, used for generating external URLs.
Defaults to `[server.protocol]://[server.host][:server.port]` if not specified.

@default ""
@environment `AFFINE_SERVER_EXTERNAL_URL`

https.description:
Whether the server is hosted on a ssl enabled domain (https://).
@default false
@environment `AFFINE_SERVER_HTTPS`

listenAddr.description:
The address to listen on (e.g., 0.0.0.0 for IPv4, :: for IPv6).
@default "0.0.0.0"
@environment `LISTEN_ADDR`

port.description:
Which port the server will listen on.
@default 3010
@environment `AFFINE_SERVER_PORT`

path.description:
Subpath where the server is deployed, if any (e.g. /localmind).
@default ""
@environment `AFFINE_SERVER_SUB_PATH`

endpoint.description:
The endpoint of the doc service.
@default ""
@environment `DOC_SERVICE_ENDPOINT`

enabled.description:
Enable permission-checked scanned PDF OCR through the server-controlled SparkClaw endpoint.
@default false
@environment `LOCALMIND_OCR_ENABLED`

baseUrl.description:
OpenAI-compatible SparkClaw OCR base URL. The server appends /chat/completions.
@default "https://sparkclaw.infinimesh.cloud/ocr/v1"
@environment `LOCALMIND_OCR_BASE_URL`

allowedHost.description:
Exact hostname allowed for outbound OCR requests.
@default "sparkclaw.infinimesh.cloud"
@environment `LOCALMIND_OCR_ALLOWED_HOST`

model.description:
Model id sent to the OpenAI-compatible OCR endpoint.
@default "sparkclaw-ocr"
@environment `LOCALMIND_OCR_MODEL`

apiKey.description:
Optional server-only bearer token for the OCR endpoint.
@default ""
@environment `LOCALMIND_OCR_API_KEY`

timeoutMs.description:
Maximum time for one OCR page inference.
@default 120000
@environment `LOCALMIND_OCR_TIMEOUT_MS`

maxUploadBytes.description:
Maximum rasterized page image size accepted by the OCR API.
@default 12582912
@environment `LOCALMIND_OCR_MAX_UPLOAD_BYTES`

maxOutputBytes.description:
Maximum cleaned Markdown bytes accepted from one OCR completion.
@default 1048576
@environment `LOCALMIND_OCR_MAX_OUTPUT_BYTES`

maxTokens.description:
Maximum completion tokens requested from the OCR model.
@default 16384
@environment `LOCALMIND_OCR_MAX_TOKENS`

maxConcurrency.description:
Maximum concurrent OCR page requests per LocalMind server process.
@default 2
@environment `LOCALMIND_OCR_MAX_CONCURRENCY`

enabled.description:
Enable the LocalMind SparkClaw ISCP integration
@default false
@environment `ISCP_ENABLED`

controllerUrl.description:
Internal URL of the LocalMind ISCP controller
@default "http://iscp-controller:8091"
@environment `ISCP_CONTROLLER_URL`

controllerToken.description:
Bearer token used between LocalMind and the ISCP controller
@default ""
@environment `ISCP_CONTROLLER_TOKEN`

domainId.description:
ISCP domain assigned to LocalMind SparkClaw endpoints
@default "localmind"
@environment `ISCP_DOMAIN_ID`

ga4.measurementId.description:
GA4 Measurement ID for Measurement Protocol.
@default ""
@environment `GA4_MEASUREMENT_ID`

ga4.apiSecret.description:
GA4 API secret for Measurement Protocol.
@default ""
@environment `GA4_API_SECRET`

externalMcp.endpoint.description:
The exact server-controlled SparkClaw Streamable HTTP MCP endpoint. Workspace clients can view but cannot change this URL.
@default "http://192.168.20.252:18790/mcp"
@environment `LOCALMIND_SPARKCLAW_MCP_ENDPOINT`

enterpriseCli.enabled.description:
Enable user-scoped enterprise CLI connectors for WeCom, Lark, and DingTalk.
@default false
@environment `LOCALMIND_ENTERPRISE_CLI_ENABLED`

enterpriseCli.rootDir.description:
Server-controlled root directory for isolated enterprise CLI profiles.
@default ".localmind/enterprise-cli"
@environment `LOCALMIND_ENTERPRISE_CLI_ROOT_DIR`

enterpriseCli.binaries.wecom.description:
Server-controlled WeCom CLI binary path or executable name.
@default "wecom-cli"
@environment `LOCALMIND_WECOM_CLI_BINARY`

enterpriseCli.binaries.lark.description:
Server-controlled Lark CLI binary path or executable name.
@default "lark-cli"
@environment `LOCALMIND_LARK_CLI_BINARY`

enterpriseCli.binaries.dingtalk.description:
Server-controlled DingTalk Workspace CLI binary path or executable name.
@default "dws"
@environment `LOCALMIND_DINGTALK_CLI_BINARY`

providers.openai.description:
The config for the openai provider.
@default {"apiKey":"","baseURL":"https://api.openai.com/v1"}
@link https://github.com/openai/openai-node

provider.apiKey.description:
Indexer search service api key. Optional for elasticsearch
@default ""
@environment `AFFINE_INDEXER_SEARCH_API_KEY`
@link https://www.elastic.co/guide/server/current/api-key.html

provider.username.description:
Indexer search service auth username, if not set, basic auth will be disabled. Optional for elasticsearch
@default ""
@environment `AFFINE_INDEXER_SEARCH_USERNAME`
@link https://www.elastic.co/guide/en/elasticsearch/reference/current/http-clients.html

provider.password.description:
Indexer search service auth password, if not set, basic auth will be disabled. Optional for elasticsearch
@default ""
@environment `AFFINE_INDEXER_SEARCH_PASSWORD`

providers.oidc.description:
OIDC OAuth provider config. Private network access requires allowPrivateNetwork: true
@default {"clientId":"","clientSecret":"","issuer":"","allowPrivateNetwork":false,"args":{}}
@link https://openid.net/specs/openid-connect-core-1_0.html

stripe.description:
Stripe sdk options and credentials
@default {"apiKey":"","webhookKey":""}
@link https://docs.stripe.com/api
